        IsBlank(ComboboxCanvasEspecie.Selected.Value),
        UpdateContext({var_validarIncluirAnimal: true})
    ),
    "Vulnerabilidade em proteções físicas",
    If(
        IsBlank(ComboboxCanvasEspecie.Selected.Value),
        UpdateContext({var_validarIncluirAnimal: true})
    )
);
If(
    var_validarIncluirAnimal = true,
    Notify(
        "Todos os campos de inclusão de animais são obrigatórios!",
        NotificationType.Error
    ),
    Patch(
        col_ListaAnimais,
        Defaults(col_ListaAnimais),
        {
            Espécie: ComboboxCanvasEspecie.Selected.Value,
            'Tipo de Registro': TextInputCanvasTipoRegistro.Value,
            'Tipo de Animal': TextInputCanvasTipoAnimal.Value,
            Tamanho: TextInputCanvasTamanho.Value,
            'Mapa de Grade': Upper(TextInputCanvasMapaGrade.Value),
            'Amostra coletada de DNA?': ComboboxCanvasDnaColetado.Selected.Value,
            'Amostras enviadas para DNA?': ComboboxCanvasDnaEnviado.Selected.Value,
            'Quantidade (Quantidade0)': Value(TextInputCanvasQuantidade.Value)
        }
    );
    Reset(ComboboxCanvasEspecie);
    Reset(TextInputCanvasTipoAnimal);
    Reset(TextInputCanvasTamanho);
    Reset(TextInputCanvasQuantidade);
    Reset(TextInputCanvasMapaGrade);
    Reset(ComboboxCanvasDnaColetado);
    Reset(ComboboxCanvasDnaEnviado)
)

If(
    var_acaoFauna = "Cadastrar",
    Remove(
        col_ListaAnimais,
        ThisItem
    ),
    Remove(
        'AIRPORTNOW - FAUNA RELACIONAMENTO',
        ThisItem
    )
);
Notify(
    "Operação realizada com sucesso!",
    NotificationType.Success,
    3000
)

If(
    var_visibleIncluirAnimais = false,
    UpdateContext({var_visibleIncluirAnimais: true});
    Reset(ComboboxCanvasEspecie);
    Reset(TextInputCanvasTipoAnimal);
    Reset(TextInputCanvasTamanho);
    Reset(TextInputCanvasQuantidade);
    Reset(TextInputCanvasMapaGrade);
    Reset(ComboboxCanvasDnaColetado);
    Reset(ComboboxCanvasDnaEnviado),
    UpdateContext({var_visibleIncluirAnimais: false})
)

If(
    var_acaoFauna = "Cadastrar",
    If(
        varItem = "Foco de atração de fauna" Or varItem = "Vulnerabilidade em proteções físicas" Or !IsBlank(
            First(
                Filter(
                    col_ListaAnimais,
                    'Tipo de Registro' = varItem
                )
            )
        ),
        DisplayMode.Edit,
        DisplayMode.Disabled
    ),
    DisplayMode.Edit
)
